public int findLargestSubstring(List<String> strings) {
        if (strings == null || strings.isEmpty()) {
            return 0;
        }

        // Initialize the result to 0
        int largest = 0;

        // Iterate over all possible substrings of each string
        for (String s : strings) {
            for (int i = 0; i < s.length(); i++) {
                for (int j = i + 1; j <= s.length(); j++) {
                    String sub = s.substring(i, j);
                    String inverse = new StringBuilder(sub).reverse().toString();

                    // Check if the substring or its inverse is found in any other string
                    boolean foundInAny = strings.stream()
                                                  .filter(s1 -> s1.equals(s) ? false : s1.contains(sub) || s1.contains(inverse))
                                                  .anyMatch(s1 -> true);

                    // Update the largest length if found
                    if (foundInAny && sub.length() > largest) {
                        largest = sub.length();
                    }
                }
            }
        }

        return largest;
    }

