    }
    if (start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    for (int[] path : paths) {
        if (path.length != 2) {
            return "cannot be travelled";
        }
    }

    // Step 2: Check if the start and end points are within the n-teresting space
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
        return "cannot be travelled";
    }
    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Step 3: Use a Set to store the paths for quick lookup
    Set<String> pathSet = new HashSet<>();
    for (int[] path : paths) {
        pathSet.add(path[0] + "," + path[1]);
    }

    // Step 4: Use a Set to keep track of visited intersections
    Set<String> visited = new HashSet<>();
    String startStr = start[0] + "," + start[1];
    String endStr = end[0] + "," + end[1];

    // Step 5: Perform a breadth-first search (BFS) to check if the end point is reachable
    Queue<String> queue = new LinkedList<>();
    queue.add(startStr);
    visited.add(startStr);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endStr)) {
            return "can be travelled";
        }

        // Check the four possible directions
        int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        for (int[] direction : directions) {
            int newX = Integer.parseInt(current.split(",")[0]) + direction[0];
            int newY = Integer.parseInt(current.split(",")[1]) + direction[1];
            String newStr = newX + "," + newY;
