    if (arr.length % 2 != 0) {
        return false;
    }

    // Create an array to store the remainders when each element is divided by k
    int[] remainderCount = new int[k];

    // Populate the remainder count array
    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Ensure the remainder is non-negative
        remainderCount[remainder]++;
    }

    // Check pairs of remainders
    for (int i = 1; i <= k / 2; i++) {
        // If the count of remainder i is not equal to the count of remainder k-i, return false
        if (remainderCount[i] != remainderCount[k - i]) {
            return false;
        }
    }

    // Special case for remainder 0
    // The count of elements with remainder 0 must be even
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // If all checks pass, it's possible to divide the array into pairs
    return true;
}

