public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 0) return 0;

    // Create an adjacency list to represent the tree
    List<List<Integer>> adjList = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adjList.add(new ArrayList<>());
    }

    // Build the adjacency list from the edges
    for (int[] edge : edges) {
        adjList.get(edge[0]).add(edge[1]);
        adjList.get(edge[1]).add(edge[0]);
    }

    // Initialize a visited array to keep track of visited nodes
    boolean[] visited = new boolean[n];

    // Helper function to perform DFS and calculate the minimum time
    int dfs(int node) {
        visited[node] = true;
        int totalTime = 0;

        // Recursively visit all children
        for (int neighbor : adjList.get(node)) {
            if (visited[neighbor]) continue;
            int timeFromNeighbor = dfs(neighbor);
            if (timeFromNeighbor > 0 || hasApple[neighbor]) {
                totalTime += 2; // Add time to travel to and from the neighbor
            }
        }

        return totalTime;
    }

    // Start DFS from node 0
    return dfs(0);
}

