public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;

    for (int num : nums) {
        sum += num;
    }

    if (n == 1) {
        return false;
    }

    boolean[][] dp = new boolean[n + 1][sum + 1];

    for (int i = 0; i <= n; i++) {
        dp[i][0] = true;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = sum; j >= nums[i - 1]; j--) {
            dp[i][j] = dp[i - 1][j] || dp[i - 1][j - nums[i - 1]];
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        for (int j = 1; j <= sum; j++) {
            if (dp[i][j]) {
                if (i * (sum - j) == (n - i) * j) {
                    return true;
                }
            }
        }
    }

    return false;
}

