public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            balance++;
        } else {
            balance--;

            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next character as it is already considered
            } else {
                insertions++; // Need to insert a closing parenthesis
            }
        }

        if (balance < 0) {
            insertions++; // Need to insert an opening parenthesis to balance
            balance = 0;
        }
    }

    return insertions + 2 * balance;
}

