public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) {
            return result;
        }

        LinkedList<Integer> queue = new LinkedList<>();
        for (int i = 0; i <= 9; i++) {
            queue.add(i);
        }

        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num >= low && num <= high) {
                result.add(num);
            }
            if (num == 0 || num > high) {
                continue;
            }

            int lastDigit = num % 10;
            if (lastDigit > 0) {
                int nextNum = num * 10 + lastDigit - 1;
                if (nextNum <= high) {
                    queue.add(nextNum);
                }
            }
            if (lastDigit < 9) {
                int nextNum = num * 10 + lastDigit + 1;
                if (nextNum <= high) {
                    queue.add(nextNum);
                }
            }
        }

        result.sort(Integer::compare);
        return result;
    }

