    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    boolean[] visited = new boolean[n];
    List<Integer> path = new ArrayList<>();
    int count = 0;

    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            visited[i] = true;
            path.add(A[i]);
            backtrack(A, visited, path, count);
            path.remove(path.size() - 1);
            visited[i] = false;
        }
    }

    return count;
}

