public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    List<List<Integer>> dp = new ArrayList<>(Collections.nCopies(n, null));
    dp.forEach(list -> list = new ArrayList<>());

    dp.get(0).add(A[0]);

    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                for (int num : dp.get(j)) {
                    dp.get(i).add(num);
                }
            }
        }
    }

    int count = 0;
    for (List<Integer> list : dp) {
        count += list.size();
    }

    return count;
}

