public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;

    boolean up = true;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            result[index++] = mat[i][j];
        }
    }

    index = 0;

    for (int k = 1; k < m + n - 1; k++) {
        int x = up ? Math.max(0, k - n + 1) : Math.min(m - 1, k);
        int y = up ? Math.min(n - 1, k) : Math.max(0, k - m + 1);

        List<Integer> temp = new ArrayList<>();
        while (x >= 0 && x < m && y >= 0 && y < n) {
            temp.add(mat[x][y]);
            x += up ? -1 : 1;
            y += up ? 1 : -1;
        }

        if (up) {
            Collections.reverse(temp);
        }

        for (int value : temp) {
            result[index++] = value;
        }

        up = !up;
    }

    return result;
}

